def ten(x):
    return 10
def ap1(f):
    return lambda x: f(x)
h1 = ap1(ten)
print(h1(1))

def dbl(x):
    return x * 2
def inc(x):
    return x + 1
def compose(f, g):
    return lambda x: f(g(x))
h3 = compose(dbl, inc)
print(h3(5))

def fold1(fn, xs, init):
    acc = init
    for x in xs:
        acc = fn(acc, x)
    return acc
print(fold1(lambda a: a * 10, [1, 2], 0))
